    ],
    "lacunas": [],
    "motivo": "Custo da linha base declarado como R$ 1.650,00, correspondente às obrigações fixas e ao apoio.",
    "unidade": "BRL_centavo"
  },
  "custo_novo": {
    "estado": "exato",
    "valor": 165000,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_b915",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_493d",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_f7ff82",
        "localizador": "L01"
      }
    ],
    "lacunas": [],
    "motivo": "O aviso não tem custo direto; as parcelas fixas não variam com o prazo e a política sem crédito preserva o valor contratado do apoio em caso de antecipação.",
    "unidade": "BRL_centavo"
  },
  "delta_centavos": {
    "estado": "exato",
    "valor": 0,
    "direcao": "zero",
    "evidencias": [
      {
        "fonte_id": "f_b915",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_493d",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_f7ff82",
        "localizador": "L01"
      }
    ],
    "lacunas": [],
    "motivo": "Não há custo direto; as obrigações fixas permanecem e não há crédito para eventual antecipação do apoio.",
    "unidade": "BRL_centavo"
  },
  "justificativa": "A variação do término não pode ser determinada sem as precedências. O custo permanece no valor base: o aviso não acrescenta custo direto, as parcelas são fixas e o apoio não recebe crédito por antecipação."
}

